		expect(events.get('Bar')).to.be.empty;
		expect(events.has('bar')).to.equal(false);
		expect(events.get('baz:bat!')).to.have.lengthOf(1);
	});

	it('should remove only the first matching listener', () => {
		const foo = () => {};
		inst.on('foo', foo);
